def tables():
    return KEYS

def read_pak(path):
    data = bytearray(Path(path).read_bytes())
    keys = tables()
    pos = 0
    version = None
    while pos < len(data):
        signature = bytes(data[pos : pos + 4])
        if signature == bytes.fromhex("af b4 fc fb"):
            fields = struct.unpack_from("<4sHHHHHIIIHH", data, pos)
            method = fields[3]
            crc, compressed, uncompressed, name_length, extra_length = fields[6:]
            start = pos + 30 + name_length + extra_length
            if version is None and uncompressed:
                for candidate, table in enumerate(keys, 1):
                    key_offset = (compressed & 31) * 32 if candidate == 1 else compressed & 1023
                    probe = bytearray(data[start : start + compressed])
                    for i in range(min(32, compressed)):
                        probe[i] ^= table[key_offset + i]
                    try:
                        plain = zlib.decompress(probe, -15) if method == 8 else bytes(probe)
                    except zlib.error:
                        continue
                    if len(plain) == uncompressed and binascii.crc32(plain) == crc:
                        version = candidate
                        break
            if version is None and compressed:
                raise ValueError("Unknown Aion PAK encoding")
            if compressed:
                table = keys[version - 1]
                key_offset = (compressed & 31) * 32 if version == 1 else compressed & 1023
                for i in range(min(32, compressed)):
                    data[start + i] ^= table[key_offset + i]
            data[pos : pos + 4] = b"PK\x03\x04"
            pos = start + compressed
        elif signature == bytes.fromhex("af b4 fe fd"):
            fields = struct.unpack_from("<4sHHHHHHIIIHHHHHII", data, pos)
            name_length, extra_length, comment_length = fields[10:13]
            data[pos : pos + 4] = b"PK\x01\x02"
            pos += 46 + name_length + extra_length + comment_length
        elif signature == bytes.fromhex("af b4 fa f9"):
            data[pos : pos + 4] = b"PK\x05\x06"
            break
        else:
            raise ValueError(f"Unexpected PAK signature at {pos}: {signature.hex()}")
    return zipfile.ZipFile(io.BytesIO(data))

def packed_int(data, pos):
    result = 0
    shift = 0
    while True:
        value = data[pos]
        pos += 1
        result |= (value & 127) << shift
        if not value & 128:
            return result, pos
        shift += 7

def binary_xml(payload):
    if payload[0] != 0x80:
        raise ValueError("Not Aion binary XML")
    size, pos = packed_int(payload, 1)
    string_data = payload[pos : pos + size]
    pos += size

    def string(index):
        if index == 0:
            return ""
        start = index * 2
        end = string_data.find(b"\x00\x00", start)
        if end < 0:
            raise ValueError("Unterminated string")
        if (end - start) & 1:
            end += 1
        return string_data[start:end].decode("utf-16le")

    def node(pos):
        name, pos = packed_int(payload, pos)
        flags = payload[pos]
        pos += 1
        value = ""
        if flags & 1:
            index, pos = packed_int(payload, pos)
            value = string(index)
        attributes = {}
        if flags & 2:
            count, pos = packed_int(payload, pos)
            for _ in range(count):
                key, pos = packed_int(payload, pos)
                val, pos = packed_int(payload, pos)
                attributes[string(key)] = string(val)
        element = ET.Element(string(name), attributes)
        if value:
            element.text = value
        if flags & 4:
            count, pos = packed_int(payload, pos)
            for _ in range(count):
                child, pos = node(pos)
                element.append(child)
        return element, pos

    root, _ = node(pos)
    return root

def encode_int(number):
    data = bytearray()
    while number > 127:
        data.append((number & 127) | 128)
        number >>= 7
    data.append(number)
    return data

def encode_binary_xml(root):
    strings = bytearray(b"\x00\x00")
    offsets = {"": 0}

    def index(value):
        if value not in offsets:
            offsets[value] = len(strings) // 2
            strings.extend(value.encode("utf-16le"))
            strings.extend(b"\x00\x00")
        return offsets[value]

    def node(element):
        attrs = element.attrib
        children = list(element)
        value = element.text or ""
        flags = (1 if value else 0) | (2 if attrs else 0) | (4 if children else 0)
        result = encode_int(index(element.tag)) + bytes([flags])
        if value:
            result += encode_int(index(value))
        if attrs:
            result += encode_int(len(attrs))
            for key, val in attrs.items():
                result += encode_int(index(key)) + encode_int(index(val))
        if children:
            result += encode_int(len(children))
            for child in children:
                result += node(child)
        return result

    nodes = node(root)
    return b"\x80" + encode_int(len(strings)) + strings + nodes

def encode_pak(zip_bytes):
    data = bytearray(zip_bytes)
    key = tables()[1]  # World.pak uses Aion PAK version 2.
    pos = 0
    while pos < len(data):
        signature = bytes(data[pos : pos + 4])
        if signature == b"PK\x03\x04":
            fields = struct.unpack_from("<4sHHHHHIIIHH", data, pos)
            compressed, name_length, extra_length = fields[7], fields[9], fields[10]
            if fields[2] & 8:
                raise ValueError("ZIP data descriptors are not supported")
            start = pos + 30 + name_length + extra_length
            for i in range(min(32, compressed)):
                data[start + i] ^= key[(compressed & 1023) + i]
            data[pos : pos + 4] = bytes.fromhex("af b4 fc fb")
            pos = start + compressed
        elif signature == b"PK\x01\x02":
            fields = struct.unpack_from("<4sHHHHHHIIIHHHHHII", data, pos)
            data[pos : pos + 4] = bytes.fromhex("af b4 fe fd")
            pos += 46 + fields[10] + fields[11] + fields[12]
        elif signature == b"PK\x05\x06":
            data[pos : pos + 4] = bytes.fromhex("af b4 fa f9")
            break
        else:
            raise ValueError(f"Unexpected ZIP signature at {pos}: {signature.hex()}")
    return data
